      reference:{waferId:ref.id,title:ref.title,note:ref.note,records:E.copy(a.records),metrics:E.summarize(a)},current:{waferId:state.active,title:entry().title,note:entry().note,records:E.copy(b.records),metrics:E.summarize(b)},
