    const x=v=>54+v/E.WIDTH*680,y=v=>22+(max-v)/(max-min)*126,path=key=>points.map((p,i)=>`${i?'L':'M'}${x(p.x_nm).toFixed(2)},${y(p[key]).toFixed(2)}`).join(' ');
