    if(step.op==='expose')return {label:'평균 유효 노광량',unit:'mJ/cm²',value:average(w.latent)};
    if(step.op==='implant'){const d=w.dopants.at(-1);return {label:'평균 투과 주입량',unit:'cm⁻²',value:d.dose*average(d.transmission)};}
