    if(step.op==='bake')return {label:'모델 노광 응답 계수',unit:'%',value:w.bakeFactor*100};
    if(step.op==='clean')return {label:'잔여 오염 지표',unit:'모델 단위',value:m.particles};
    if(['cmp','measure','probe'].includes(step.op))return {label:'표면 최대–최소 단차',unit:'nm',value:m.topography};
